<script setup>
import {ref,onMounted,computed,inject} from 'vue';import {get,api} from '../api/client';import FoodRecordForm from '../components/FoodRecordForm.vue';import ApprovedPrices from '../components/ApprovedPrices.vue';import CursorPager from '../components/CursorPager.vue';import EvidenceViewer from '../components/EvidenceViewer.vue';import ArchiveDialog from '../components/ArchiveDialog.vue';import {Search,Plus,Trash2,RotateCcw,ArrowUpRight,Package,X,FileText,Pencil,Save} from 'lucide-vue-next';
const editing=ref(false),saving=ref(false),draft=ref(null),editReason=ref(''),editError=ref(''),saved=ref('');
function open(row){selected.value=row;evidence.value=[];editing.value=false;editError.value='';saved.value=''}
function startEdit(){draft.value=JSON.parse(JSON.stringify(selected.value.food_record));editReason.value='';editError.value='';editing.value=true}
async function saveEdit(){if(saving.value)return;saving.value=true;editError.value='';try{const result=await api('/foods/'+selected.value.id,{method:'PATCH',etag:'"'+selected.value.version+'"',body:{food_record:draft.value,reason:editReason.value}});selected.value=result.data;data.value.items=data.value.items.map(row=>row.id===result.data.id?result.data:row);editing.value=false;saved.value='식품 속성을 저장했습니다. 승인된 단가는 별도로 표시하며, 자료 가격 수정으로 변경되지 않습니다.'}catch(e){editError.value=e.message}finally{saving.value=false}}
const user=inject('user'),canManage=computed(()=>user.value.roles.some(r=>['admin','reviewer'].includes(r)));const data=ref({items:[]}),query=ref(''),error=ref(''),loading=ref(false),selected=ref(null),evidence=ref([]),archived=ref(false),confirm=ref(null),notice=ref(null);async function load(cursor=''){error.value='';loading.value=true;try{data.value=await get('/foods?'+new URLSearchParams({q:query.value,archived:String(archived.value),...(cursor?{cursor}:{})}));selected.value=null;evidence.value=[]}catch(e){error.value=e.message}finally{loading.value=false}}onMounted(()=>load());async function completed(result){notice.value={...result,title:confirm.value.food_record.food_name};confirm.value=null;await load()}async function undo(){try{await api('/foods/'+notice.value.id+(notice.value.archived?'/restore':''),{method:notice.value.archived?'POST':'DELETE',body:{archive_version:notice.value.archive_version,reason:'직전 작업 실행 취소'}});notice.value=null;await load()}catch(e){error.value=e.message}}
</script><template><div class="page-heading"><div><div class="section-kicker">식품 관리</div><h1>식품 목록</h1><p class="muted">업체가 달라도 같은 기준으로. 식품 정보와 근거를 한곳에서 관리하세요.</p></div><div class="row"><RouterLink to="/prices" class="secondary">단가표 조회</RouterLink><RouterLink to="/documents" class="primary"><Plus :size="17"/> 자료에서 식품 추가</RouterLink></div></div><div v-if="notice" class="action-notice" role="status"><span><b>{{notice.title}}</b> {{notice.archived?'목록에서 삭제했습니다.':'복구했습니다.'}}</span><button class="link" @click="undo">실행 취소</button></div><p v-if="error" class="error" role="alert">{{error}}</p><section class="panel food-directory"><div class="directory-toolbar"><div class="segmented" aria-label="식품 목록 구분"><button :class="{active:!archived}" @click="archived=false;load()"><Package :size="15"/> 식품 목록</button><button :class="{active:archived}" @click="archived=true;load()"><Trash2 :size="15"/> 삭제한 식품</button></div><form class="search-control" @submit.prevent="load()"><Search :size="17"/><input v-model="query" placeholder="식품명, 업체, 코드 검색" aria-label="식품 검색"><button type="submit">검색</button></form></div><div class="directory-caption"><span>{{loading?'불러오는 중…':`${data.items.length}개 표시`}}</span><span>식품을 선택하면 속성·규격·원문을 확인할 수 있습니다.</span></div><div class="table-scroll"><table class="food-directory-table"><thead><tr><th>식품명</th><th>업체</th><th>규격</th><th>승인된 단가</th><th>공통식품코드</th><th>알레르기 정보</th><th class="table-actions">관리</th></tr></thead><tbody><tr v-for="row in data.items" :key="row.id" class="clickable" @click="open(row)"><td><button class="food-name" @click.stop="open(row)">{{row.food_record.food_name}}<ArrowUpRight :size="14"/></button><span v-if="row.food_record.attributes.flavor" class="cell-sub">{{row.food_record.attributes.flavor}}</span></td><td>{{row.food_record.company_name||'—'}}</td><td><span class="spec-chip" v-if="row.food_record.specification.quantity">{{row.food_record.specification.quantity}}{{row.food_record.specification.unit}}<span v-if="row.food_record.specification.sales_unit"> / {{row.food_record.specification.sales_unit}}</span></span><span v-else>{{row.food_record.specification.original_text||'—'}}</span><small v-if="row.food_record.specification.pack_count" class="cell-sub">{{row.food_record.specification.piece_quantity}}{{row.food_record.specification.piece_unit}} × {{row.food_record.specification.pack_count}}입</small></td><td><template v-for="price in row.approved_prices||[]" :key="price.id"><b>{{Number(price.value.amount).toLocaleString()}}원</b><small class="cell-sub">/ {{price.value.quantity}}{{price.value.unit}} · {{price.effective_state==='scheduled'?'적용 예정':'현재 적용'}}</small></template><span v-if="!row.approved_prices?.length" class="muted">등록된 단가 없음</span></td><td class="code-cell">{{row.food_record.food_code||'—'}}</td><td><span :class="['allergy-state',{known:row.food_record.allergens.review_status!=='unknown'}]">{{{unknown:'미확인',source_declared:'원문 표시',reviewed:'검토 완료'}[row.food_record.allergens.review_status]}}</span></td><td class="table-actions"><button v-if="canManage" class="row-action" :aria-label="row.food_record.food_name+(row.archived?' 복구':' 삭제')" @click.stop="confirm=row"><RotateCcw v-if="row.archived" :size="17"/><Trash2 v-else :size="17"/></button></td></tr></tbody></table></div><div v-if="!data.items.length&&!loading" class="directory-empty"><Package :size="34"/><h3>{{archived?'삭제한 식품이 없습니다.':'아직 등록된 식품이 없습니다.'}}</h3><p>{{query?'검색어를 바꿔 다시 조회해 주세요.':archived?'삭제한 식품은 이곳에서 복구할 수 있습니다.':'자료를 가져와 추출 결과를 확인하면 목록에 등록됩니다.'}}</p><RouterLink v-if="!archived&&!query" to="/documents" class="primary">첫 자료 가져오기</RouterLink></div><CursorPager :next="data.next_cursor" @next="load"/></section><div v-if="selected" class="drawer-backdrop" @click.self="selected=null"><aside class="food-drawer" role="dialog" aria-modal="true" aria-label="식품 상세"><div class="drawer-header"><div><span class="section-kicker">식품 상세</span><h2>{{selected.food_record.food_name}}</h2><p>{{selected.food_record.company_name||'업체 미기재'}}</p></div><button class="row-action" @click="selected=null" aria-label="상세 닫기"><X :size="21"/></button></div><div class="drawer-content"><p v-if="saved" class="notice" role="status">{{saved}}</p><p v-if="editError" class="error" role="alert">{{editError}}</p><ApprovedPrices :prices="selected.approved_prices||[]" @evidence="evidence=$event"/><FoodRecordForm v-if="editing" v-model="draft" :readonly="saving"/><FoodRecordForm v-else :model-value="selected.food_record" readonly/><label v-if="editing">수정 사유<textarea v-model="editReason" :disabled="saving" placeholder="어떤 정보를 왜 수정했는지 입력해 주세요." maxlength="1000" rows="2"/></label><EvidenceViewer v-if="evidence.length" :ids="evidence"/></div><div v-if="editing" class="drawer-footer"><button class="secondary" :disabled="saving" @click="editing=false;editError=''">취소</button><button class="primary" :disabled="saving||!editReason.trim()" @click="saveEdit"><Save :size="15"/>{{saving?'저장 중…':'수정 저장'}}</button></div><div v-else class="drawer-footer"><button v-if="canManage&&!selected.archived" class="primary" @click="startEdit"><Pencil :size="15"/> 수정</button><RouterLink :to="'/products/'+selected.product_id" class="secondary">단가·이력 <ArrowUpRight :size="15"/></RouterLink><button class="secondary" @click="evidence=selected.evidence_ids"><FileText :size="15"/> 근거</button><button v-if="canManage" :class="selected.archived?'primary':'danger-outline'" @click="confirm=selected">{{selected.archived?'복구':'삭제'}}</button></div></aside></div><ArchiveDialog v-if="confirm" :item="confirm" kind="food" @close="confirm=null" @done="completed"/></template>
